`timescale 1ps/1ps
// Testbench for the whole axis_weighted_buffer v1.3 (AXI-Lite registers, weight
// stream, matched filter, accumulated and decimated buffers, read-back streams),
// parameters as in the lab ZCU216 build. It runs a command script written by
// model.py and dumps what the buffers return; model.py compares with numpy.
//
// The DSP multiplier dsp_macro_0 is Xilinx's own simulation model, generated by
// run.sh from the IP's .xci (not a behavioural stand-in).
//
// Input stream: sample k (k counts valid beats from 0) is word k % NDATA of
// data.hex, 32 bits per line, lower 16 bits I, upper 16 bits Q (the readout's
// format). +GAP=n (n>0) drops tvalid on a pseudo-random ~1/n of cycles and puts
// junk on tdata while tvalid is low; GAP=0 (default) is a continuous stream.
//
// Script commands, one per line (numbers decimal):
//   reg R V               AXI-Lite write V to register R (byte address 4*R)
//   wgt ADDR N FILE       load N weight words from FILE (hex, 32 bits per line)
//                         as QickSoc.load_weights does: reg13=ADDR, reg3=4,
//                         DMA stream on s1_axis, reg3=0
//   trig D W [N SP]       raise the trigger in the readout clock cycle in which
//                         sample k0+D is on s_axis (k0 = next sample when the
//                         command is read), hold it W readout cycles; with N and
//                         SP, a train of N triggers SP samples apart. The sample
//                         number of each trigger is printed as "TRIG k".
//   align P               wait until the next sample to be presented, K, has
//                         (K+1) % P == 0 (then "trig 0 ..." starts the window
//                         at data index 0 mod P)
//   wait D                wait until D more samples have been presented
//   avg ADDR LEN FILE     read LEN accumulated words (reg4/reg5, reg3=1) into FILE
//   buf ADDR LEN FILE     read LEN decimated words (reg8/reg9, reg3=2) into FILE
//   end
module tb;
  localparam N_AVG = 13, N_BUF = 12, B = 16;
  parameter N_WGT = 13;     // xelab -generic_top N_WGT=14 for the 14-bit build

  reg aclk = 0;  always #5000 aclk = ~aclk;   // AXI-Lite / weight DMA, 100 MHz
  reg sclk = 0;  always #1627 sclk = ~sclk;   // readout stream, ~307 MHz
  reg mclk = 0;  always #4000 mclk = ~mclk;   // read-back streams, 125 MHz
  reg rstn = 0;

  // AXI-Lite
  reg  [5:0]  awaddr = 0; reg awvalid = 0; wire awready;
  reg  [31:0] wdata = 0;  reg wvalid = 0;  wire wready;
  wire [1:0]  bresp;      wire bvalid;     reg bready = 0;
  reg  [5:0]  araddr = 0; reg arvalid = 0; wire arready;
  wire [31:0] rdata; wire [1:0] rresp; wire rvalid; reg rready = 0;

  // weight stream
  reg s1_tvalid = 0; reg [31:0] s1_tdata = 0; wire s1_tready;
  // data stream
  reg s_tvalid = 0; reg [31:0] s_tdata = 0; wire s_tready;
  reg trigger = 0;
  // outputs
  wire m0_tvalid, m0_tlast; wire [63:0] m0_tdata;
  wire m1_tvalid, m1_tlast; wire [31:0] m1_tdata;
  wire m2_tvalid; wire [63:0] m2_tdata;

  axis_weighted_buffer #(.N_AVG(N_AVG), .N_BUF(N_BUF), .N_WGT(N_WGT), .B(B)) dut (
    .s_axi_aclk(aclk), .s_axi_aresetn(rstn),
    .s_axi_awaddr(awaddr), .s_axi_awprot(3'b0), .s_axi_awvalid(awvalid), .s_axi_awready(awready),
    .s_axi_wdata(wdata), .s_axi_wstrb(4'hf), .s_axi_wvalid(wvalid), .s_axi_wready(wready),
    .s_axi_bresp(bresp), .s_axi_bvalid(bvalid), .s_axi_bready(bready),
    .s_axi_araddr(araddr), .s_axi_arprot(3'b0), .s_axi_arvalid(arvalid), .s_axi_arready(arready),
    .s_axi_rdata(rdata), .s_axi_rresp(rresp), .s_axi_rvalid(rvalid), .s_axi_rready(rready),
    .trigger(trigger),
    .s1_axis_tvalid(s1_tvalid), .s1_axis_tdata(s1_tdata), .s1_axis_tready(s1_tready),
    .s_axis_aclk(sclk), .s_axis_aresetn(rstn),
    .s_axis_tvalid(s_tvalid), .s_axis_tready(s_tready), .s_axis_tdata(s_tdata),
    .m_axis_aclk(mclk), .m_axis_aresetn(rstn),
    .m0_axis_tvalid(m0_tvalid), .m0_axis_tready(1'b1), .m0_axis_tdata(m0_tdata), .m0_axis_tlast(m0_tlast),
    .m1_axis_tvalid(m1_tvalid), .m1_axis_tready(1'b1), .m1_axis_tdata(m1_tdata), .m1_axis_tlast(m1_tlast),
    .m2_axis_tvalid(m2_tvalid), .m2_axis_tready(1'b1), .m2_axis_tdata(m2_tdata));

  // ---------------- input stream ----------------
  localparam MAXD = 1 << 16;
  reg [31:0] data [0:MAXD-1];
  integer ndata = 0, gap = 0;
  integer k = 0;                 // index of the next sample to present
  integer trig_at = -1, trig_w = 0, trig_cnt = 0;
  integer trig_q [$];
  reg [31:0] lfsr = 32'h1;
  always @(posedge sclk) begin
    if (!rstn) begin
      s_tvalid <= 0;
    end else begin
      lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
      if (gap > 0 && (lfsr % gap) == 0) begin
        s_tvalid <= 0;
        s_tdata  <= 32'h8001_7ffe ^ lfsr;   // junk on invalid cycles
      end else begin
        s_tvalid <= 1;
        s_tdata  <= data[k % ndata];
        if (k == trig_at) begin
          trig_cnt = trig_w; $display("TRIG %0d", k);
          trig_at = (trig_q.size() > 0) ? trig_q.pop_front() : -1;
        end
        k = k + 1;
      end
      if (trig_cnt > 0) begin trigger <= 1; trig_cnt = trig_cnt - 1; end
      else trigger <= 0;
    end
  end

  // ---------------- AXI-Lite ----------------
  task automatic axi_write(input integer r, input [31:0] v);
    @(posedge aclk);
    awaddr <= r * 4; awvalid <= 1; wdata <= v; wvalid <= 1; bready <= 1;
    fork
      begin @(posedge aclk); while (!awready) @(posedge aclk); awvalid <= 0; end
      begin @(posedge aclk); while (!wready)  @(posedge aclk); wvalid  <= 0; end
    join
    while (!bvalid) @(posedge aclk);
    @(posedge aclk); bready <= 0;
    repeat (4) @(posedge aclk);
  endtask

  // ---------------- weights ----------------
  reg [31:0] wbuf [0:(1<<N_WGT)-1];
  task automatic load_weights(input integer addr, input integer n, input string fname);
    integer i;
    for (i = 0; i < n; i++) wbuf[i] = 0;
    $readmemh(fname, wbuf, 0, n-1);
    axi_write(13, addr);
    axi_write(3, 4);
    repeat (10) @(posedge aclk);            // WE_REG resync, READ_START_ADDR, WAIT_TVALID
    i = 0;
    @(posedge aclk);
    s1_tvalid <= 1; s1_tdata <= wbuf[0];
    while (i < n) begin
      @(posedge aclk);
      if (s1_tready) begin
        i = i + 1;
        if (i < n) s1_tdata <= wbuf[i]; else s1_tvalid <= 0;
      end
    end
    repeat (10) @(posedge aclk);
    axi_write(3, 0);
  endtask

  // ---------------- read-back ----------------
  task automatic read_back(input integer sel, input integer addr, input integer len, input string fname);
    integer fd, got, t;
    fd = $fopen(fname, "w");
    got = 0; t = 0;
    if (sel == 1) begin axi_write(4, addr); axi_write(5, len); end
    else          begin axi_write(8, addr); axi_write(9, len); end
    fork
      axi_write(3, sel);
      begin
        while (got < len && t < 20000) begin
          @(posedge mclk); t = t + 1;
          if (sel == 1 && m0_tvalid) begin $fdisplay(fd, "%016h", m0_tdata); got = got + 1; end
          if (sel == 2 && m1_tvalid) begin $fdisplay(fd, "%08h",  m1_tdata); got = got + 1; end
        end
      end
    join
    repeat (20) @(posedge mclk);
    axi_write(3, 0);
    $fclose(fd);
    if (got != len) $display("ERROR read_back sel=%0d got %0d of %0d", sel, got, len);
  endtask

  // ---------------- script ----------------
  initial begin
    string script, line, cmd, fname;
    integer fd, a1, a2, n, i, x;
    if (!$value$plusargs("SCRIPT=%s", script)) script = "script.txt";
    if (!$value$plusargs("GAP=%d", gap)) gap = 0;
    begin
      integer dfd; dfd = $fopen("data.hex", "r");
      while (!$feof(dfd) && ndata < MAXD) begin
        if ($fscanf(dfd, "%h\n", x) == 1) begin data[ndata] = x; ndata = ndata + 1; end
      end
      $fclose(dfd);
    end
    $display("INFO %0d data words, GAP=%0d", ndata, gap);
    #100000 rstn = 1;
    #200000;
    fd = $fopen(script, "r");
    while (!$feof(fd)) begin
      n = $fgets(line, fd);
      if (n == 0) continue;
      n = $sscanf(line, "%s", cmd);
      if (cmd == "reg") begin
        n = $sscanf(line, "%s %d %d", cmd, a1, a2); axi_write(a1, a2);
      end else if (cmd == "wgt") begin
        n = $sscanf(line, "%s %d %d %s", cmd, a1, a2, fname); load_weights(a1, a2, fname);
      end else if (cmd == "trig") begin
        integer k0, cnt_t, sp;
        k0 = k;
        n = $sscanf(line, "%s %d %d %d %d", cmd, a1, a2, cnt_t, sp);
        if (n < 5) begin cnt_t = 1; sp = 0; end
        trig_w = a2;
        trig_q.delete();
        for (i = 1; i < cnt_t; i++) trig_q.push_back(k0 + a1 + i*sp);
        trig_at = k0 + a1;
        while (trig_at != -1 || trig_q.size() != 0 || trig_cnt != 0) @(posedge sclk);
      end else if (cmd == "align") begin
        // continue when the next sample presented, K, has (K+1) % P == 0
        n = $sscanf(line, "%s %d", cmd, a1);
        @(posedge sclk); while (((k + 1) % a1) != 0) @(posedge sclk);
      end else if (cmd == "wait") begin
        n = $sscanf(line, "%s %d", cmd, a1); a1 = k + a1; while (k < a1) @(posedge sclk);
      end else if (cmd == "avg") begin
        n = $sscanf(line, "%s %d %d %s", cmd, a1, a2, fname); read_back(1, a1, a2, fname);
      end else if (cmd == "buf") begin
        n = $sscanf(line, "%s %d %d %s", cmd, a1, a2, fname); read_back(2, a1, a2, fname);
      end else if (cmd == "end") break;
      cmd = "";
    end
    $fclose(fd);
    $display("DONE at sample %0d", k);
    $finish;
  end
endmodule
